internal fun sampleLedgerCloseMetaExtXdr(seed: Int, depth: Int): LedgerCloseMetaExtXdr =
  when (seed.mod(2)) {
    0 -> sampleLedgerCloseMetaExtXdrVoidArm(seed, depth)
    else -> sampleLedgerCloseMetaExtXdrV1Arm(seed + 3, depth)
  }

internal fun sampleLedgerCloseMetaV1Xdr(seed: Int, depth: Int): LedgerCloseMetaV1Xdr = LedgerCloseMetaV1Xdr(
  sampleLedgerCloseMetaExtXdr(seed, depth + 1),
  sampleLedgerHeaderHistoryEntryXdr(seed + 3, depth + 1),
  sampleGeneralizedTransactionSetXdr(seed + 6, depth + 1),
  if (depth < SAMPLE_DEPTH) List(1) { sampleTransactionResultMetaXdr(seed + 9 + it, depth + 1) } else emptyList(),
  if (depth < SAMPLE_DEPTH) List(1) { sampleUpgradeEntryMetaXdr(seed + 12 + it, depth + 1) } else emptyList(),
  if (depth < SAMPLE_DEPTH) List(1) { sampleSCPHistoryEntryXdr(seed + 15 + it, depth + 1) } else emptyList(),
  sampleUint64Xdr(seed + 18, depth + 1),
  if (depth < SAMPLE_DEPTH) List(1) { sampleLedgerKeyXdr(seed + 21 + it, depth + 1) } else emptyList(),
  if (depth < SAMPLE_DEPTH) List(1) { sampleLedgerEntryXdr(seed + 24 + it, depth + 1) } else emptyList()
)

internal fun sampleLedgerCloseMetaV2Xdr(seed: Int, depth: Int): LedgerCloseMetaV2Xdr = LedgerCloseMetaV2Xdr(
  sampleLedgerCloseMetaExtXdr(seed, depth + 1),
  sampleLedgerHeaderHistoryEntryXdr(seed + 3, depth + 1),
  sampleGeneralizedTransactionSetXdr(seed + 6, depth + 1),
  if (depth < SAMPLE_DEPTH) List(1) { sampleTransactionResultMetaV1Xdr(seed + 9 + it, depth + 1) } else emptyList(),
  if (depth < SAMPLE_DEPTH) List(1) { sampleUpgradeEntryMetaXdr(seed + 12 + it, depth + 1) } else emptyList(),
  if (depth < SAMPLE_DEPTH) List(1) { sampleSCPHistoryEntryXdr(seed + 15 + it, depth + 1) } else emptyList(),
  sampleUint64Xdr(seed + 18, depth + 1),
  if (depth < SAMPLE_DEPTH) List(1) { sampleLedgerKeyXdr(seed + 21 + it, depth + 1) } else emptyList()
)

internal fun sampleLedgerCloseMetaXdrV0Arm(seed: Int, depth: Int): LedgerCloseMetaXdr =
  LedgerCloseMetaXdr.V0(sampleLedgerCloseMetaV0Xdr(seed, depth + 1))

internal fun sampleLedgerCloseMetaXdrV1Arm(seed: Int, depth: Int): LedgerCloseMetaXdr =
  LedgerCloseMetaXdr.V1(sampleLedgerCloseMetaV1Xdr(seed, depth + 1))

internal fun sampleLedgerCloseMetaXdrV2Arm(seed: Int, depth: Int): LedgerCloseMetaXdr =
  LedgerCloseMetaXdr.V2(sampleLedgerCloseMetaV2Xdr(seed, depth + 1))

internal fun sampleLedgerCloseMetaXdr(seed: Int, depth: Int): LedgerCloseMetaXdr =
  when (seed.mod(3)) {
    0 -> sampleLedgerCloseMetaXdrV0Arm(seed, depth)
    1 -> sampleLedgerCloseMetaXdrV1Arm(seed + 3, depth)
    else -> sampleLedgerCloseMetaXdrV2Arm(seed + 6, depth)
  }

/**
 * XDR-JSON (SEP-0051) rendering, decoding and rejection behaviour of the types
 * generated from Stellar-ledger.x.
 */
class XdrJsonLedgerTest {

  @Test
  fun upgradeTypeXdrRoundTripsThroughItsJsonTree() {
    assertRoundTripUpgradeTypeXdr(sampleUpgradeTypeXdr(7, 0))
    assertRoundTripUpgradeTypeXdr(sampleUpgradeTypeXdr(7, SAMPLE_DEPTH))
  }

  private fun assertRoundTripUpgradeTypeXdr(value: UpgradeTypeXdr) {
    val tree = value.toXdrJsonElement()
    val text = UpgradeTypeXdr.fromXdrJsonElement(tree).toXdrJson()
    assertEquals(tree, UpgradeTypeXdr.fromXdrJson(text).toXdrJsonElement())
    assertEquals(text, UpgradeTypeXdr.fromXdrJson(text).toXdrJson())

    val writer = XdrWriter()
    UpgradeTypeXdr.fromXdrJsonElement(tree).encode(writer)
    assertEquals(tree, UpgradeTypeXdr.decode(XdrReader(writer.toByteArray())).toXdrJsonElement())
  }

  @Test
  fun upgradeTypeXdrRejectsInputOfTheWrongShape() {
    assertFailsWith<IllegalArgumentException> { UpgradeTypeXdr.fromXdrJsonElement(JsonNull) }
  }


  @Test
  fun stellarValueTypeXdrRendersStellarValueBasicAsBasic() {
    val member = StellarValueTypeXdr.STELLAR_VALUE_BASIC
    assertEquals(0, member.value)
    assertEquals(JsonPrimitive("basic"), member.toXdrJsonElement())
    assertEquals("\"basic\"", member.toXdrJson())
    assertEquals(member, StellarValueTypeXdr.fromXdrJson("\"basic\""))
    assertEquals(member, StellarValueTypeXdr.fromXdrJsonElement(JsonPrimitive("basic")))
  }

  @Test
  fun stellarValueTypeXdrRendersStellarValueSignedAsSigned() {
    val member = StellarValueTypeXdr.STELLAR_VALUE_SIGNED
    assertEquals(1, member.value)
    assertEquals(JsonPrimitive("signed"), member.toXdrJsonElement())
    assertEquals("\"signed\"", member.toXdrJson())
    assertEquals(member, StellarValueTypeXdr.fromXdrJson("\"signed\""))
    assertEquals(member, StellarValueTypeXdr.fromXdrJsonElement(JsonPrimitive("signed")))
  }

